INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'accent', 'n.', '/ˈæksent/', '口音;腔调', 'In Montreal many people spoke English with a French accent.', '在蒙特利尔,许多人说英语带着法语口音。', 'Journey Across a Vast Land', 1, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a French accent', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'advertisement', 'n.', '/ədˈvɜːtɪsmənt/', '广告;启事', 'At the station all the signs and advertisements were in French.', '在车站,所有的标识和广告都是法语的。', 'Journey Across a Vast Land', 2, 0, 'senior', 'wordlist', 'elective2', 'U4', 'signs and advertisements', '美音 /ˌædvərˈtaɪzmənt/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'airline', 'n.', '/ˈeəlaɪn/', '航空公司', 'We took the train instead of a flight with any airline.', '我们选择坐火车,而没有乘任何航空公司的航班。', 'Journey Across a Vast Land', 3, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a busy airline', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'alongside', 'prep./adv.', '/əˌlɒŋˈsaɪd/', '在……旁边;与……一起;在旁边', 'We sat in a restaurant alongside the broad St Lawrence River.', '我们坐在宽阔的圣劳伦斯河边的一家餐馆里。', 'Journey Across a Vast Land', 4, 0, 'senior', 'wordlist', 'elective2', 'U4', 'alongside the river', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'anticipate', 'vt.', '/ænˈtɪsɪpeɪt/', '预料;预见;期望', 'The girls did not anticipate seeing such an open country.', '姑娘们没有料到会看到这样一片开阔的国土。', 'Journey Across a Vast Land', 5, 0, 'senior', 'wordlist', 'elective2', 'U4', 'anticipate seeing', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'antique', 'n./adj.', '/ænˈtiːk/', '古物;古董;古老的;古董的', 'They admired the antique furniture dating back to the 17th century.', '他们欣赏着可追溯到17世纪的古董家具。', 'Journey Across a Vast Land', 6, 0, 'senior', 'wordlist', 'elective2', 'U4', 'an antique shop', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'anyhow', 'adv.', '/ˈenihaʊ/', '(转换话题时)不过;反正', '"Anyhow, the next station is my stop," Anna said.', '“不过,下一站就是我下车的地方,”安娜说。', 'Journey Across a Vast Land', 7, 0, 'senior', 'wordlist', 'elective2', 'U4', 'Anyhow, ...', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'arise', 'vi.', '/əˈraɪz/', '出现;产生;起身', 'Should a chance to travel arise, I would love to cross Canada by rail.', '若有机会出行,我很想坐火车横穿加拿大。', 'Journey Across a Vast Land', 8, 0, 'senior', 'wordlist', 'elective2', 'U4', 'problems arise', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'breath', 'n.', '/breθ/', '呼吸;一口气', 'The beauty of the lake took the visitors'' breath away.', '湖的美景令游客惊叹不已。', 'Journey Across a Vast Land', 9, 0, 'senior', 'wordlist', 'elective2', 'U4', 'take one''s breath away', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'bunch', 'n.', '/bʌntʃ/', '束;串;一群;大量', 'From the train they saw a bunch of farms covering a large area.', '他们从火车上看到一片片占地很广的农场。', 'Journey Across a Vast Land', 10, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a bunch of farms', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'coherent', 'adj.', '/kəʊˈhɪərənt/', '有条理的;清楚易懂的', 'Her travel diary was clear and coherent from start to finish.', '她的旅行日记从头到尾清晰而有条理。', 'Journey Across a Vast Land', 11, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a coherent account', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'contrary', 'adj./n.', '/ˈkɒntrəri/', '相反的;相反的事实', 'Contrary to what many people believe, China has vast empty spaces.', '与许多人的看法相反,中国有大片空旷之地。', 'Journey Across a Vast Land', 12, 0, 'senior', 'wordlist', 'elective2', 'U4', 'contrary to', '美音 /ˈkɑːntreri/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'craft', 'n.', '/krɑːft/', '手艺;工艺;技艺', 'Along St Paul Street we watched artists practising their craft.', '在圣保罗街上,我们看着艺术家们施展手艺。', 'Journey Across a Vast Land', 13, 0, 'senior', 'wordlist', 'elective2', 'U4', 'local crafts', '美音 /kræft/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'curtain', 'n.', '/ˈkɜːtn/', '窗帘', 'When they pulled back the curtain, they could see Lake Huron.', '他们拉开窗帘时,便能看见休伦湖。', 'Journey Across a Vast Land', 14, 0, 'senior', 'wordlist', 'elective2', 'U4', 'pull back the curtain', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'drill', 'v./n.', '/drɪl/', '钻(孔);训练;钻头;演习', 'Workers had to drill through the rock to build the railway.', '工人们必须钻穿岩石来修建这条铁路。', 'Journey Across a Vast Land', 15, 0, 'senior', 'wordlist', 'elective2', 'U4', 'drill a hole', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'duration', 'n.', '/djuˈreɪʃn/', '持续时间;期间', 'Their trip from Vancouver to Toronto had taken a duration of four days.', '他们从温哥华到多伦多的旅程持续了四天。', 'Journey Across a Vast Land', 16, 0, 'senior', 'wordlist', 'elective2', 'U4', 'for the duration', '美音 /duˈreɪʃn/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'dusk', 'n.', '/dʌsk/', '黄昏;傍晚', 'They met Lin Fei around dusk over dinner downtown.', '他们在黄昏时分于市中心共进晚餐,见到了林菲。', 'Journey Across a Vast Land', 17, 0, 'senior', 'wordlist', 'elective2', 'U4', 'at dusk', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'freeze', 'v.', '/friːz/', '结冰;(使)冻住', 'When Lake Louise freezes over in winter, people skate on it.', '冬天路易斯湖结冰时,人们便在上面滑冰。', 'Journey Across a Vast Land', 18, 0, 'senior', 'wordlist', 'elective2', 'U4', 'freeze over', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'freezing', 'adj.', '/ˈfriːzɪŋ/', '极冷的;冰冻的', 'It was freezing cold on the prairie, with frost on the ground.', '草原上极其寒冷,地面上结着霜。', 'Journey Across a Vast Land', 19, 0, 'senior', 'wordlist', 'elective2', 'U4', 'freezing cold', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'frost', 'n./v.', '/frɒst/', '霜;霜冻;使蒙上霜', 'There was frost on the ground, confirming that autumn had arrived.', '地面上结着霜,证实秋天已经来临。', 'Journey Across a Vast Land', 20, 0, 'senior', 'wordlist', 'elective2', 'U4', 'frost on the ground', '美音 /frɔːst/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'goat', 'n.', '/ɡəʊt/', '山羊', 'High in the Rockies, the travellers spotted wild mountain goats.', '在落基山高处,旅行者看到了野生的山羊。', 'Journey Across a Vast Land', 21, 0, 'senior', 'wordlist', 'elective2', 'U4', 'mountain goats', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'harbour', 'n.', '/ˈhɑːbə(r)/', '海港;港口', 'Vancouver has a fine harbour with mountains looking out over the city.', '温哥华有一个良港,群山俯瞰着这座城市。', 'Journey Across a Vast Land', 22, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a busy harbour', '美式拼 harbor');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'highlight', 'n./vt.', '/ˈhaɪlaɪt/', '最精彩的部分;突出;强调', 'Seeing the Great Lakes was the highlight of their whole journey.', '看到五大湖是他们整个旅程中最精彩的部分。', 'Journey Across a Vast Land', 23, 0, 'senior', 'wordlist', 'elective2', 'U4', 'the highlight of the trip', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'idiom', 'n.', '/ˈɪdiəm/', '习语;成语', 'Anna taught them the idiom "as flat as a pancake".', '安娜教他们“像煎饼一样平”这个习语。', 'Journey Across a Vast Land', 24, 0, 'senior', 'wordlist', 'elective2', 'U4', 'an English idiom', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'literally', 'adv.', '/ˈlɪtərəli/', '字面上;确实地;简直', 'The prairie was literally as flat as the eye could see.', '那片草原简直平坦得一望无际。', 'Journey Across a Vast Land', 25, 0, 'senior', 'wordlist', 'elective2', 'U4', 'literally flat', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'mall', 'n.', '/mɔːl/', '购物商场;购物广场', 'Edmonton has one of the largest shopping malls in North America.', '埃德蒙顿有北美最大的购物商场之一。', 'Journey Across a Vast Land', 26, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a shopping mall', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'massive', 'adj.', '/ˈmæsɪv/', '巨大的;非常严重的', 'Canada is a massive country with vast and empty spaces.', '加拿大是一个幅员辽阔、空旷无人的巨大国家。', 'Journey Across a Vast Land', 27, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a massive country', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'mist', 'n.', '/mɪst/', '薄雾;水汽', 'They were astonished to see mist rising from the great falls.', '他们惊讶地看到薄雾从大瀑布上升起。', 'Journey Across a Vast Land', 28, 0, 'senior', 'wordlist', 'elective2', 'U4', 'misty clouds', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'misty', 'adj.', '/ˈmɪsti/', '多雾的;模糊的', 'Misty clouds hung over Niagara Falls in the early morning.', '清晨,薄雾笼罩在尼亚加拉瀑布上空。', 'Journey Across a Vast Land', 29, 0, 'senior', 'wordlist', 'elective2', 'U4', 'misty clouds', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'owe', 'vt.', '/əʊ/', '欠(账、情等);把……归功于', '"You owe it to yourselves to stay in Montreal longer," he said.', '“你们应该让自己在蒙特利尔多待些日子,”他说。', 'Journey Across a Vast Land', 30, 0, 'senior', 'wordlist', 'elective2', 'U4', 'owe it to oneself', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'peak', 'n.', '/piːk/', '顶峰;山峰;尖形', 'Snow still covered the high peaks of the Canadian Rockies.', '积雪仍覆盖着加拿大落基山脉的高峰。', 'Journey Across a Vast Land', 31, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a mountain peak', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'photographer', 'n.', '/fəˈtɒɡrəfə(r)/', '摄影师;拍照者', 'A young photographer named Jean-Philippe sat down with them.', '一位名叫让-菲利普的年轻摄影师在他们旁边坐下。', 'Journey Across a Vast Land', 32, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a young photographer', '美音 /fəˈtɑːɡrəfər/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'pleasant', 'adj.', '/ˈpleznt/', '令人愉快的;友好的', 'They must have spent a pleasant evening together at the party.', '他们在聚会上一定度过了一个愉快的夜晚。', 'Journey Across a Vast Land', 33, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a pleasant evening', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'prairie', 'n.', '/ˈpreəri/', '(北美)大草原', 'The train headed southeast across the great Canadian Prairie.', '火车向东南方向驶过辽阔的加拿大大草原。', 'Journey Across a Vast Land', 34, 0, 'senior', 'wordlist', 'elective2', 'U4', 'the Canadian Prairie', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'proceed', 'vi.', '/prəˈsiːd/', '行进;继续做;进而做', 'They had a few hours before they had to proceed to Montreal.', '在必须继续前往蒙特利尔之前,他们还有几个小时。', 'Journey Across a Vast Land', 35, 0, 'senior', 'wordlist', 'elective2', 'U4', 'proceed to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'quarry', 'n.', '/ˈkwɒri/', '采石场', 'Butchart Gardens was transformed from an old quarry.', '布查特花园是由一座旧采石场改造而成的。', 'Journey Across a Vast Land', 36, 0, 'senior', 'wordlist', 'elective2', 'U4', 'an old quarry', '美音 /ˈkwɔːri/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'scenery', 'n.', '/ˈsiːnəri/', '风景;景色', 'Seen from the top of the hill, the scenery was truly fascinating.', '从山顶望去,那景色着实令人着迷。', 'Journey Across a Vast Land', 37, 0, 'senior', 'wordlist', 'elective2', 'U4', 'beautiful scenery', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'shore', 'n.', '/ʃɔː(r)/', '岸;滨', 'From the CN Tower they looked across the shores of Lake Ontario.', '他们从加拿大国家电视塔上眺望安大略湖的湖岸。', 'Journey Across a Vast Land', 38, 0, 'senior', 'wordlist', 'elective2', 'U4', 'the shores of the lake', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'spectacular', 'adj./n.', '/spekˈtækjələ(r)/', '壮观的;壮丽的;壮丽的场面', 'The Rocky Mountains offered the most spectacular views of the trip.', '落基山脉呈现出这趟旅程中最壮观的景色。', 'Journey Across a Vast Land', 39, 0, 'senior', 'wordlist', 'elective2', 'U4', 'spectacular views', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'steel', 'n.', '/stiːl/', '钢;钢铁工业', 'The girls saw hundreds of skyscrapers of glass and steel.', '姑娘们看到了数百座玻璃和钢铁建成的摩天大楼。', 'Journey Across a Vast Land', 40, 0, 'senior', 'wordlist', 'elective2', 'U4', 'glass and steel', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'thunder', 'v./n.', '/ˈθʌndə(r)/', '轰隆隆地响(移动);打雷;雷声', 'The train thundered on through the rolling hills of Ontario.', '火车轰隆隆地驶过安大略起伏的丘陵。', 'Journey Across a Vast Land', 41, 0, 'senior', 'wordlist', 'elective2', 'U4', 'thunder on', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'toast', 'n./vt.', '/təʊst/', '烤面包片;干杯;为……干杯;烤', 'In Montreal they loved good coffee, toast, and cheese.', '在蒙特利尔,他们喜爱香浓的咖啡、吐司和奶酪。', 'Journey Across a Vast Land', 42, 0, 'senior', 'wordlist', 'elective2', 'U4', 'coffee and toast', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'urban', 'adj.', '/ˈɜːbən/', '城市的;市镇的', 'After the prairie they were back in an urban area, the city of Winnipeg.', '穿过草原后,他们又回到了城市,即温尼伯市。', 'Journey Across a Vast Land', 43, 0, 'senior', 'wordlist', 'elective2', 'U4', 'an urban area', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'eventually', 'adv.', '/ɪˈventʃuəli/', '最终;终于', 'After another day on the train, they eventually reached Winnipeg.', '在火车上又过了一天后,他们最终抵达了温尼伯。', 'Journey Across a Vast Land', 44, 0, 'senior', 'wordlist', 'elective2', 'U4', 'eventually arrive', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'wealthy', 'adj.', '/ˈwelθi/', '富有的;富裕的', 'Toronto is the largest and wealthiest city in Canada.', '多伦多是加拿大最大、最富裕的城市。', 'Journey Across a Vast Land', 45, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a wealthy city', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'skyscraper', 'n.', '/ˈskaɪskreɪpə(r)/', '摩天大楼', 'Downtown Toronto is full of tall glass skyscrapers.', '多伦多市中心满是高高的玻璃摩天大楼。', 'Journey Across a Vast Land', 46, 0, 'senior', 'wordlist', 'elective2', 'U4', 'hundreds of skyscrapers', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e2u4.01', '①作定语:doing(主动/进行) vs done(被动/完成)', 'A2', 11, '选择性必修二 U4 — 分词作定语修饰名词:被修饰词是动作的发出者(主动)或动作正在进行 → 用现在分词 doing(the train heading west / falling leaves);被修饰词是动作的承受者(被动)或动作已完成 → 用过去分词 done(the road covered with snow / fallen leaves)。', 1, 'elective2', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e2u4.02', '②作状语:doing(主动) vs done(被动)', 'A2', 11, '选择性必修二 U4 — 分词作状语,逻辑主语就是句子主语:主语主动发出动作 → 用现在分词 doing(Seeing the view, she smiled);主语承受动作(被动)→ 用过去分词 done(Seen from the hill, the lake looks blue)。', 2, 'elective2', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e2u4.03', '③作宾语补足语:see/hear/find + sb/sth + doing(主动进行) vs done(被动完成)', 'A2', 11, '选择性必修二 U4 — 感官/使役动词后的宾语补足语:宾语主动做某事、动作在进行 → 用现在分词 doing(I saw him crossing the street);宾语承受动作、动作被动完成 → 用过去分词 done(I had my ticket checked / found the window broken)。', 3, 'elective2', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'From the window we watched the train ____ west across the open prairie.', 'heading', 'headed', 'to head', 'head', 'A', 'train 主动''朝西行驶''、动作进行中 → 现在分词 heading。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'The road ____ with deep snow was hard for the bus to climb.', 'covering', 'covered', 'to cover', 'covers', 'B', 'road 被雪覆盖、是承受者(被动)→ 过去分词 covered。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'The maple leaves ____ to the ground turned the path bright red.', 'falling', 'to fall', 'fallen', 'fall', 'C', 'leaves 已经落地、动作完成(fall 是不及物动词,完成用过去分词)→ fallen。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'We saw a bunch of farms ____ a very large area beside the railway.', 'covered', 'to cover', 'cover', 'covering', 'D', 'farms 主动''覆盖/占据''一片地、动作进行 → 现在分词 covering。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'The signs ____ in French puzzled the two girls at the Montreal station.', 'written', 'writing', 'to write', 'write', 'A', 'signs 被写成法语、是承受者(被动)→ 过去分词 written。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'The river ____ quietly alongside the railway looked silver in the moonlight.', 'flowed', 'flowing', 'to flow', 'flows', 'B', 'river 主动''流淌''、动作进行 → 现在分词 flowing。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'An old garden ____ from a quarry has now become a famous destination.', 'transforming', 'to transform', 'transformed', 'transform', 'C', 'garden 由采石场被改造、是承受者(被动/完成)→ 过去分词 transformed。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'Mist ____ from the falls slowly drifted across the lake at dawn.', 'risen', 'to rise', 'rise', 'rising', 'D', 'mist 主动''升起''、动作进行 → 现在分词 rising。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'The cobblestone streets ____ with old brick buildings gave the town a European feel.', 'lined', 'lining', 'to line', 'line', 'A', 'streets 两旁''被''老砖楼排列、是承受者(被动)→ 过去分词 lined。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'The hills ____ gently towards the lake were red, gold, and orange.', 'rolled', 'rolling', 'to roll', 'roll', 'B', 'hills 主动''起伏延伸''、动作进行 → 现在分词 rolling。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'We finally reached a city ____ on the southern border of Ontario.', 'locating', 'to locate', 'located', 'locate', 'C', 'city ''位于''某处,locate 此处是被动/完成 → 过去分词 located。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'The passengers ____ out of the windows pointed at the distant snowy peaks.', 'looked', 'to look', 'look', 'looking', 'D', 'passengers 主动''向外看''、动作进行 → 现在分词 looking。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'The wheat fields ____ by golden light stretched as far as the eye could see.', 'lit', 'lighting', 'to light', 'light', 'A', 'fields 被金光照亮、是承受者(被动)→ 过去分词 lit。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'A train ____ along the St Lawrence River sped towards the east coast.', 'sped', 'speeding', 'to speed', 'speed', 'B', 'train 主动''飞驰''、动作进行 → 现在分词 speeding。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'The tickets ____ at the gate were quickly returned to the travellers.', 'checking', 'to check', 'checked', 'check', 'C', 'tickets 被检查、是承受者(被动)→ 过去分词 checked。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'The advertisements ____ on the walls were all printed in two languages.', 'hung', 'to hang', 'hang', 'hanging', 'D', 'advertisements ''挂在''墙上、是承受者(被动/完成,hang 此处被动)→ 过去分词 hung。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'The young photographer ____ beside the river offered to show them the old town.', 'sitting', 'to sit', 'sat', 'sit', 'A', 'photographer 主动''坐着''、状态进行 → 现在分词 sitting。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'The lovely shops ____ along St Paul Street sold local crafts and antiques.', 'lined', 'lining', 'to line', 'line', 'B', 'shops ''排列''在街旁,此处强调被动排布、是承受者 → 过去分词 lined。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'Frost ____ on the cold ground confirmed that autumn had arrived in Canada.', 'formed', 'to form', 'forming', 'form', 'C', 'frost 主动''形成/出现''、动作进行 → 现在分词 forming。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.01'), 'The harbour ____ by tall mountains was one of the highlights of Vancouver.', 'surrounding', 'to surround', 'surround', 'surrounded', 'D', 'harbour 被群山环绕、是承受者(被动)→ 过去分词 surrounded。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ the autumn colours from the top of the hill, I was completely amazed.', 'Seeing', 'Seen', 'To be seen', 'See', 'A', '逻辑主语 I 主动''看见''→ 现在分词 Seeing(主动)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ from the top of the mountain, the lake looked deep blue.', 'Seeing', 'Seen', 'To see', 'See', 'B', '逻辑主语 lake 被''看'',是承受者(被动)→ 过去分词 Seen。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ eastwards, you will soon pass the snowy Canadian Rockies.', 'Headed', 'To head', 'Heading', 'Head', 'C', '逻辑主语 you 主动''朝东行进''→ 现在分词 Heading(主动)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ by its new manager, the small airline finally began to make a profit.', 'Leading', 'To lead', 'Lead', 'Led', 'D', '逻辑主语 airline 被新经理领导,是承受者(被动)→ 过去分词 Led。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ what the trip meant to him, the old man said it was unforgettable.', 'Asked', 'Asking', 'To ask', 'Ask', 'A', '逻辑主语 the old man 被问,是承受者(被动)→ 过去分词 Asked。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ along the broad river, the train rocked us gently to sleep.', 'Sped', 'Speeding', 'To speed', 'Speed', 'B', '逻辑主语 the train 主动''飞驰''→ 现在分词 Speeding。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ from a quarry long ago, the gardens now attract thousands of visitors.', 'Transforming', 'To transform', 'Transformed', 'Transform', 'C', '逻辑主语 the gardens 被改造,是承受者(被动/完成)→ 过去分词 Transformed。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ the same long rail journey before, the girls knew what to expect.', 'Taken', 'To take', 'Take', 'Having taken', 'D', '逻辑主语 the girls 主动''(曾)乘坐''、动作在前完成 → 现在分词完成式 Having taken(主动)。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ in French, the signs at the station confused the two travellers.', 'Written', 'Writing', 'To write', 'Write', 'A', '逻辑主语 the signs 被写成法语,是承受者(被动)→ 过去分词 Written。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ out of the window, the girls watched the prairie roll past.', 'Looked', 'Looking', 'To look', 'Look', 'B', '逻辑主语 the girls 主动''向外看''→ 现在分词 Looking。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ by the spectacular falls, the visitors stood in complete silence.', 'Amazing', 'To amaze', 'Amazed', 'Amaze', 'C', '逻辑主语 the visitors 被''震撼'',是感受的承受者(被动)→ 过去分词 Amazed。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ the wide stretch of the lake, Liu Qian reached for her camera.', 'Noticed', 'To notice', 'Notice', 'Noticing', 'D', '逻辑主语 Liu Qian 主动''注意到''→ 现在分词 Noticing。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ with deep snow, the mountain road remained closed all winter.', 'Blocked', 'Blocking', 'To block', 'Block', 'A', '逻辑主语 the road 被雪封住,是承受者(被动)→ 过去分词 Blocked。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ for a coffee, Anna pointed out the famous sights along the way.', 'Stopped', 'Stopping', 'To stop', 'Stop', 'B', '逻辑主语 Anna 主动''停下来''→ 现在分词 Stopping。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ at the harbour, the tired travellers were warmly welcomed by Lin Fei.', 'Arriving', 'To arrive', 'Arrived', 'Arrive', 'C', 'arrive 是不及物动词,作状语表''已到达、动作完成''用过去分词 → Arrived。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ from the CN Tower, the whole city of Toronto looked tiny.', 'Viewing', 'To view', 'View', 'Viewed', 'D', '逻辑主语 the city 被''看/俯瞰'',是承受者(被动)→ 过去分词 Viewed。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ down the curtain, Daiyu saw the bright lights of Winnipeg.', 'Pulling', 'Pulled', 'To pull', 'Pull', 'A', '逻辑主语 Daiyu 主动''拉下窗帘''→ 现在分词 Pulling。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ in two languages, the menu surprised the visitors from China.', 'Printing', 'Printed', 'To print', 'Print', 'B', '逻辑主语 the menu 被印成两种语言,是承受者(被动)→ 过去分词 Printed。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ a few hours to spare, the cousins went on a quick tour of the city.', 'Had', 'To have', 'Having', 'Have', 'C', '逻辑主语 the cousins 主动''拥有''几小时空闲 → 现在分词 Having(主动)。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.02'), '____ by the railway''s history, the photographer began to tell us many stories.', 'Fascinating', 'To fascinate', 'Fascinate', 'Fascinated', 'D', '逻辑主语 the photographer 被铁路历史迷住,是感受承受者(被动)→ 过去分词 Fascinated。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'From the platform we saw an old man ____ the railway track slowly.', 'crossing', 'crossed', 'to crossing', 'crosses', 'A', '宾语 an old man 主动''穿过''、动作进行 → 现在分词 crossing。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'At the gate Liu Qian had her ticket ____ by a friendly officer.', 'checking', 'checked', 'to check', 'check', 'B', '宾语 her ticket 被检查、被动完成 → 过去分词 checked(have sth done)。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'Through the window we watched the prairie ____ slowly past the train.', 'rolled', 'to roll', 'rolling', 'rolls', 'C', '宾语 the prairie 主动''缓缓掠过''、动作进行 → 现在分词 rolling。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'When we woke up, we found the ground ____ with a thin layer of frost.', 'covering', 'to cover', 'cover', 'covered', 'D', '宾语 the ground 被霜覆盖、被动完成 → 过去分词 covered。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'On the lake we could hear the wild geese ____ as they flew south.', 'calling', 'called', 'to call', 'calls', 'A', '宾语 the wild geese 主动''鸣叫''、动作进行 → 现在分词 calling。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'Back at the hotel, Daiyu found her bag already ____ by the staff.', 'packing', 'packed', 'to pack', 'pack', 'B', '宾语 her bag 被打包好、被动完成 → 过去分词 packed。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'From the tower they watched a few old-fashioned cars ____ by below.', 'rolled', 'to roll', 'rolling', 'roll', 'C', '宾语 cars 主动''驶过''、动作进行 → 现在分词 rolling。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'When she returned, Liu Qian found the curtain ____ back by the wind.', 'pulling', 'to pull', 'pull', 'pulled', 'D', '宾语 the curtain 被风拉开、被动完成 → 过去分词 pulled。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'Standing by the falls, we could feel the cold mist ____ against our faces.', 'blowing', 'blown', 'to blow', 'blows', 'A', '宾语 the cold mist 主动''吹拂''、动作进行 → 现在分词 blowing。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'At the museum the girls saw many old maps ____ carefully on the walls.', 'hanging', 'hung', 'to hang', 'hang', 'B', '宾语 maps 被挂在墙上、被动完成 → 过去分词 hung。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'From our seats we noticed snow ____ silently outside the train window.', 'fallen', 'to fall', 'falling', 'falls', 'C', '宾语 snow 主动''飘落''、动作进行 → 现在分词 falling。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'After the storm, the travellers found a few trees ____ across the track.', 'blowing', 'to blow', 'blow', 'blown', 'D', '宾语 a few trees 被风刮倒在轨道上、被动完成 → 过去分词 blown。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'On the platform we saw a porter ____ heavy suitcases onto the train.', 'loading', 'loaded', 'to load', 'loads', 'A', '宾语 a porter 主动''搬运''、动作进行 → 现在分词 loading。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'At the station the girls heard their train number ____ over the speakers.', 'announcing', 'announced', 'to announce', 'announce', 'B', '宾语 their train number 被广播、被动完成 → 过去分词 announced。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'From the bridge we watched the broad river ____ towards the distant sea.', 'flowed', 'to flow', 'flowing', 'flows', 'C', '宾语 the river 主动''流向''大海、动作进行 → 现在分词 flowing。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'Before leaving, Daiyu had her photos ____ at a small shop downtown.', 'printing', 'to print', 'print', 'printed', 'D', '宾语 her photos 被冲印、被动完成 → 过去分词 printed(have sth done)。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'Up in the Rockies we saw a herd of mountain goats ____ along the cliffs.', 'climbing', 'climbed', 'to climb', 'climbs', 'A', '宾语 goats 主动''攀爬''、动作进行 → 现在分词 climbing。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'When the lake freezes over, you often see it ____ with skaters all day.', 'filling', 'filled', 'to fill', 'fill', 'B', '宾语 it(the lake)被滑冰者挤满、被动状态 → 过去分词 filled。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'From the train window the girls watched the autumn leaves ____ in the wind.', 'danced', 'to dance', 'dancing', 'dances', 'C', '宾语 the autumn leaves 主动''飞舞''、动作进行 → 现在分词 dancing。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U4' AND code='e2u4.03'), 'At the border the officer had all the bags ____ before the train moved on.', 'searching', 'to search', 'search', 'searched', 'D', '宾语 all the bags 被检查、被动完成 → 过去分词 searched。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Across the Great Canadian Prairie', 'From Edmonton, the train headed southeast across the great Canadian Prairie. At school, Daiyu and Liu Qian had learnt that Canada''s population is only a little over thirty-seven million. Even so, they did not anticipate seeing such an open country, and were truly amazed. They went through two wheat-growing provinces, where a bunch of farms covered a very large area. After another day on the train, they were finally back in an urban area, the city of Winnipeg. From there they travelled through the night and woke up in Ontario, a land of forests and lakes. The train thundered on through the rolling hills, while the bushes and maple trees outside their windows shone red, gold, and orange. There was frost on the ground, confirming that autumn had arrived. The girls realised that this vast and empty land was nothing like the crowded country many foreigners imagine China to be.', '记叙·横穿大草原', 150, '[{"q":"How did the girls feel about the Canadian Prairie?","answer":"A","options":["They were amazed by how open and empty it was.","They thought it looked exactly like home.","They found it crowded and noisy.","They were bored and wanted to leave."],"explanation":"原文 ''did not anticipate seeing such an open country, and were truly amazed'' 的转述。"},{"q":"What told the girls that autumn had come?","answer":"B","options":["The wheat had just been planted.","The trees had turned colour and frost lay on the ground.","The lakes had completely frozen over.","The farms were empty of people."],"explanation":"原文 maple trees 变红金橙 + ''frost on the ground, confirming that autumn had arrived'' 的概括转述。"},{"q":"What did the journey help the girls understand about China?","answer":"A","options":["That China, too, has wide and empty spaces, unlike what some foreigners think.","That China has no large cities.","That China and Canada share the same weather.","That China is also far smaller than Canada."],"explanation":"末句 ''this vast and empty land was nothing like the crowded country many foreigners imagine China to be'' 的转述。"}]'::jsonb, '[{"word":"prairie","cn":"大草原"},{"word":"anticipate","cn":"预料"},{"word":"urban","cn":"城市的"},{"word":"frost","cn":"霜"},{"word":"thunder","cn":"轰隆隆地行进"}]'::jsonb, 2, 'elective2', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Through the Canadian Rockies', 'Of all the sights along the railway, the Canadian Rockies left the deepest impression on the two travellers. As the train climbed higher, snow-covered peaks rose on every side, and the air grew thin and cold. Far below, a green river flowed quietly through the valley, and from time to time the girls spotted mountain goats moving along the steep cliffs. Near a small mountain town, the train passed Lake Louise, whose water was a strange, milky blue. Anna, a local passenger, told them that in winter the lake freezes over completely, and people skate and play on the thick ice. Heading west of here, the railway runs down to the coast at Vancouver, a city with a fine harbour and mountains looking out over the streets. Seen from the train, the Rockies seemed almost unreal, like a painting that kept changing shape. The girls agreed that this part of the trip was the true highlight of their journey across Canada.', '说明·落基山风光', 161, '[{"q":"What did the girls see as the train climbed into the Rockies?","answer":"B","options":["Wide wheat fields and busy farms.","Snowy peaks, a valley river, and goats on the cliffs.","Tall glass skyscrapers everywhere.","A flat land with no hills at all."],"explanation":"原文描述 snow-covered peaks、green river、mountain goats 的概括转述。"},{"q":"According to Anna, what happens at Lake Louise in winter?","answer":"C","options":["The water turns warm enough to swim in.","The lake dries up completely.","The frozen lake becomes a place to skate and play.","Boats sail across it all day."],"explanation":"原文 ''in winter the lake freezes over completely, and people skate and play on the thick ice'' 的转述。"},{"q":"How did the girls feel about this part of the trip?","answer":"D","options":["They thought it was dull compared with the cities.","They wished they had flown instead.","They were frightened and stayed in their seats.","They felt it was the best part of the whole journey."],"explanation":"末句 ''this part of the trip was the true highlight of their journey'' 的转述。"}]'::jsonb, '[{"word":"peak","cn":"山峰"},{"word":"goat","cn":"山羊"},{"word":"freeze over","cn":"结冰"},{"word":"harbour","cn":"港口"},{"word":"highlight","cn":"最精彩的部分"}]'::jsonb, 2, 'elective2', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'A Few Hours in Toronto', 'After their long ride from the west, Daiyu and her cousin reached Toronto, the largest and wealthiest city in Canada. They had only a few hours before they had to proceed to Montreal, so they decided to make the most of the time. First they went up the famous tower and looked across the shores of Lake Ontario. Standing high above the streets, they were astonished to see misty clouds rising in the distance from the great falls on the south side of the lake. Down below, hundreds of skyscrapers of glass and steel shone in the afternoon sun, while a few old-fashioned cars rolled slowly by. As they walked north from the harbour, Daiyu suddenly remembered that an old schoolmate of her mother''s lived in the city. She phoned the woman, and around dusk the three of them shared dinner in a busy Chinatown. Over the meal, their host explained that Chinese people had been settling there for more than a hundred years, which was why such wonderful food from all over China could be found in the city.', '记叙·多伦多见闻', 180, '[{"q":"Why did the girls have to use their time carefully in Toronto?","answer":"A","options":["They soon had to travel on to Montreal.","The city was about to close for the night.","They had lost their train tickets.","It was raining too hard to go out."],"explanation":"原文 ''only a few hours before they had to proceed to Montreal'' 的转述。"},{"q":"What surprised the girls when they looked out from the tower?","answer":"B","options":["Snow falling over the wheat fields.","Misty clouds rising from the falls in the distance.","A train speeding along the river.","A harbour full of fishing boats."],"explanation":"原文 ''astonished to see misty clouds rising in the distance from the great falls'' 的转述。"},{"q":"Why could such good Chinese food be found in the city?","answer":"C","options":["Because the city was close to China.","Because the food was flown in every day.","Because Chinese people had lived there for over a century.","Because no other food was sold there."],"explanation":"末句 ''Chinese people had been settling there for more than a hundred years'' 的转述。"}]'::jsonb, '[{"word":"wealthy","cn":"富裕的"},{"word":"proceed","cn":"继续前往"},{"word":"shore","cn":"湖岸"},{"word":"skyscraper","cn":"摩天大楼"},{"word":"dusk","cn":"黄昏"}]'::jsonb, 2, 'elective2', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'The French City of Montreal', 'The train left Toronto late at night and reached Montreal early the next morning. The moment the girls stepped onto the platform, they noticed something different: all around them, people were speaking French. The signs and advertisements were in French too, and even those who spoke English did so with a soft accent. "We don''t leave until this evening," Liu Qian said, "so let''s go and see the old town by the water." They spent a pleasant afternoon wandering through lovely shops and watching artists practise their craft along an old street. As they sat in a restaurant alongside the broad St Lawrence River, a young photographer named Jean-Philippe joined them. When he heard that they had only one day in the city, he shook his head and said they really owed it to themselves to stay longer. Montreal, he explained, had its own special culture, where most people spoke both English and French, and where good coffee, music, and food were part of everyday life.', '记叙·蒙特利尔的法语风情', 166, '[{"q":"What did the girls first notice in Montreal?","answer":"D","options":["That the city was completely empty.","That it was much colder than Toronto.","That there were no shops at all.","That everyone around them was speaking French."],"explanation":"原文 ''all around them, people were speaking French'' 的转述。"},{"q":"How did the girls spend their afternoon?","answer":"A","options":["They visited shops and watched artists at work near the river.","They rested at the station the whole time.","They climbed a tall tower.","They went skating on a frozen lake."],"explanation":"原文 ''wandering through lovely shops and watching artists practise their craft'' 的转述。"},{"q":"What was Jean-Philippe''s advice to the girls?","answer":"B","options":["To leave the city as soon as possible.","To stay in Montreal longer than one day.","To learn French before travelling.","To take a plane to their next stop."],"explanation":"原文 ''they really owed it to themselves to stay longer'' 的转述。"}]'::jsonb, '[{"word":"accent","cn":"口音"},{"word":"advertisement","cn":"广告"},{"word":"alongside","cn":"在……旁边"},{"word":"craft","cn":"手艺"},{"word":"owe","cn":"应该(欠……情)"}]'::jsonb, 2, 'elective2', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Why Travel by Rail?', 'Some people ask why anyone would spend four days on a train when a plane can cross Canada in only a few hours. For travellers like Daiyu and Liu Qian, however, the slow journey is exactly the point. On a plane you see little more than clouds, but from a train window the whole land slides past: wheat fields, rolling hills, misty lakes, and snowy peaks. A rail trip also gives you time to think, to read, and to talk with the people sitting around you. It was on the train that the girls met Anna, a friendly local who taught them Canadian idioms and described the scenery along the way. By car you must keep your eyes on the road, but on a train you are free to watch the world go by. Of course, the train is slower, and a long ride can feel tiring. Even so, many travellers believe that a journey across a vast land should be enjoyed mile by mile, not rushed through high above the clouds.', '议论·为什么坐火车旅行', 172, '[{"q":"Why do travellers like the girls choose the train over the plane?","answer":"C","options":["Because the train is always cheaper.","Because planes do not fly across Canada.","Because the slow ride lets them enjoy the whole land along the way.","Because they are afraid of flying."],"explanation":"原文 ''the slow journey is exactly the point'' + 看遍 land 的转述。"},{"q":"What is one advantage of the train over the car, according to the text?","answer":"D","options":["The train never gets tiring.","The train is faster than a car.","Cars cannot cross rivers.","On a train you can watch the scenery instead of watching the road."],"explanation":"原文 ''By car you must keep your eyes on the road, but on a train you are free to watch the world go by'' 的转述。"},{"q":"What does the writer admit is a weakness of rail travel?","answer":"A","options":["A long ride can be slow and tiring.","You cannot meet anyone on a train.","You see nothing but clouds.","Trains never reach big cities."],"explanation":"原文 ''the train is slower, and a long ride can feel tiring'' 的转述。"}]'::jsonb, '[{"word":"idiom","cn":"习语"},{"word":"scenery","cn":"风景"},{"word":"peak","cn":"山峰"},{"word":"misty","cn":"多雾的"}]'::jsonb, 2, 'elective2', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Building the Railway Across Canada', 'The railway that carried Daiyu and Liu Qian across Canada was not always there. More than a hundred years ago, the country''s eastern and western parts were separated by thousands of kilometres of forest, prairie, and high mountains. Leaders dreamed of joining them with a single line of steel, but the work proved hard and dangerous. Builders had to drill through solid rock, cross freezing rivers, and lay track over endless empty plains. Many workers came from far away, and a great number of them were Chinese. They worked through burning summers and freezing winters, and sadly many lost their lives in the mountains. When the line was at last finished, it tied the distant cities together and allowed people and goods to move from coast to coast. Today, travellers can sit in a warm carriage and watch the spectacular scenery roll by, but they should remember the countless hands that once cut this path through such a vast and difficult land.', '说明·横贯铁路的历史', 162, '[{"q":"What separated the eastern and western parts of Canada long ago?","answer":"B","options":["A single line of steel.","Vast distances of woodland, open plains, and tall mountains.","A large frozen lake.","A wall built by the workers."],"explanation":"原文 ''separated by thousands of kilometres of forest, prairie, and high mountains'' 的转述。"},{"q":"What does the text say about the workers who built the railway?","answer":"C","options":["They all came from nearby towns.","They finished the work in a single summer.","Many travelled from distant places, and quite a few were Chinese.","They never faced any danger."],"explanation":"原文 ''Many workers came from far away, and a great number of them were Chinese'' 的转述。"},{"q":"What does the writer want today''s travellers to remember?","answer":"D","options":["That the train is faster than a plane.","That the railway was easy to build.","That the scenery is not worth seeing.","The many people whose hard work created the railway."],"explanation":"末句 ''they should remember the countless hands that once cut this path'' 的转述。"}]'::jsonb, '[{"word":"steel","cn":"钢铁"},{"word":"drill","cn":"钻(孔)"},{"word":"freezing","cn":"极冷的"},{"word":"spectacular","cn":"壮观的"}]'::jsonb, 2, 'elective2', 'U4');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U4', 'Morning on the Train', 'On the third morning, Daiyu woke early and quietly pulled back the (1)____ beside her seat. Outside, a thin white (2)____ lay on the fields, and the rising sun turned the sky pink. The train (3)____ gently on through the rolling hills, rocking the sleepy passengers from side to side. Far away she could see a low (4)____ of blue mountains. A friendly local woman sitting (5)____ her smiled and said good morning. "This is the best (6)____ of the whole trip," the woman whispered, "when the land is still and quiet." Daiyu nodded and took a deep (7)____ of the cool morning air. She felt lucky to be (8)____ across such a vast country by rail. By the time the others (9)____ up, the train was already passing a small town. Daiyu reached for her camera, eager to (10)____ the beauty of the scene.', 145, 2, '[{"q":"1","answer":"A","options":["curtain","harbour","accent","quarry"],"explanation":"pull back the curtain 拉开窗帘。"},{"q":"2","answer":"B","options":["mall","frost","steel","goat"],"explanation":"white frost 白霜。"},{"q":"3","answer":"C","options":["froze","owed","thundered","drilled"],"explanation":"thundered on 轰隆隆地前行。"},{"q":"4","answer":"D","options":["bunch","shore","peak","row"],"explanation":"a low row of mountains 一排低矮的山。"},{"q":"5","answer":"A","options":["alongside","despite","across","between"],"explanation":"sitting alongside her 坐在她旁边。"},{"q":"6","answer":"B","options":["accent","highlight","duration","idiom"],"explanation":"the best highlight/part 最精彩的部分。"},{"q":"7","answer":"C","options":["mall","peak","breath","craft"],"explanation":"take a deep breath 深吸一口气。"},{"q":"8","answer":"D","options":["selling","buying","hiding","travelling"],"explanation":"travelling across 横穿旅行。"},{"q":"9","answer":"A","options":["woke","froze","sold","drilled"],"explanation":"woke up 醒来。"},{"q":"10","answer":"B","options":["forget","capture","waste","drop"],"explanation":"capture the beauty 捕捉美景。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U4', 'A Town on the Prairie', 'When the train stopped at a small (1)____ town, Liu Qian got off to stretch her legs. The land here was (2)____ flat, stretching to the horizon in every direction. A (3)____ of farms spread out beyond the station, their wheat already golden. The cold air smelt of (4)____ and dry grass. An old farmer, (5)____ for the next train, told her that winters here were (6)____ cold, with temperatures far below zero. "In summer, though," he added, "the days are long and (7)____." Liu Qian was (8)____ to learn that such a quiet place could feel so alive. Before she climbed back on board, the farmer gave her a small loaf of bread and a cup of hot (9)____. She thanked him warmly, (10)____ that even a short stop could leave a lasting memory.', 135, 2, '[{"q":"1","answer":"C","options":["urban","antique","prairie","misty"],"explanation":"a prairie town 草原小镇。"},{"q":"2","answer":"D","options":["hardly","rarely","never","literally"],"explanation":"literally flat 简直平坦。"},{"q":"3","answer":"A","options":["bunch","shore","peak","drill"],"explanation":"a bunch of farms 一片农场。"},{"q":"4","answer":"B","options":["steel","frost","toast","mall"],"explanation":"smelt of frost 闻起来有霜冻的气息。"},{"q":"5","answer":"C","options":["selling","freezing","waiting","drilling"],"explanation":"waiting for the train 等火车。"},{"q":"6","answer":"D","options":["pleasant","wealthy","coherent","freezing"],"explanation":"freezing cold 极冷的。"},{"q":"7","answer":"A","options":["pleasant","frozen","broken","urban"],"explanation":"long and pleasant 漫长而宜人。"},{"q":"8","answer":"B","options":["bored","amazed","afraid","angry"],"explanation":"amazed 惊讶的。"},{"q":"9","answer":"C","options":["steel","frost","coffee","peak"],"explanation":"a cup of hot coffee 一杯热咖啡。"},{"q":"10","answer":"D","options":["forgetting","losing","hiding","realising"],"explanation":"realising 意识到。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U4', 'Dawn in the Rockies', 'The train began to climb, and soon snowy (1)____ rose on both sides of the track. Daiyu had never seen such (2)____ scenery in her life. A green river flowed far below, and a few wild mountain (3)____ moved carefully along the steep cliffs. As the sun rose, (4)____ clouds drifted slowly between the peaks. "(5)____ from down in the valley," Anna said, "these mountains look even taller." The air was so cold that (6)____ formed on the inside of the windows. Daiyu wiped the glass and (7)____ out at a small blue lake. Anna explained that in winter the lake (8)____ over, and people skate on the thick ice. "You really (9)____ it to yourself to come back in winter," she added with a smile. Daiyu promised that one day she would (10)____ to this beautiful place.', 138, 2, '[{"q":"1","answer":"A","options":["peaks","malls","shores","drills"],"explanation":"snowy peaks 雪峰。"},{"q":"2","answer":"B","options":["urban","spectacular","freezing","wealthy"],"explanation":"spectacular scenery 壮观的景色。"},{"q":"3","answer":"C","options":["malls","accents","goats","crafts"],"explanation":"mountain goats 山羊。"},{"q":"4","answer":"D","options":["frozen","broken","wealthy","misty"],"explanation":"misty clouds 薄雾般的云。"},{"q":"5","answer":"A","options":["Seen","Seeing","To see","Sees"],"explanation":"Seen from the valley 从山谷望去(被动,主语 mountains 被看)。"},{"q":"6","answer":"B","options":["steel","frost","toast","mall"],"explanation":"frost formed 结霜。"},{"q":"7","answer":"C","options":["sold","froze","looked","drilled"],"explanation":"looked out 向外看。"},{"q":"8","answer":"D","options":["sells","drills","owes","freezes"],"explanation":"freezes over 结冰。"},{"q":"9","answer":"A","options":["owe","sell","freeze","drill"],"explanation":"owe it to yourself 你应该(给自己)。"},{"q":"10","answer":"B","options":["forget","return","lose","drop"],"explanation":"return to this place 重返此地。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U4', 'First Hours in Montreal', 'The two cousins arrived in Montreal early in the morning, tired but (1)____. As they walked through the station, they were surprised to hear everyone speaking French. Even the (2)____ on the walls were printed in French. Some people spoke English with a soft (3)____. "(4)____ to what we expected, this feels like a European town," Liu Qian said. They decided to (5)____ to the old part of the city, which lay close to the water. There they wandered through lovely shops full of (6)____ furniture and local crafts. By (7)____, the streets had filled with the warm smell of coffee and fresh bread. A young (8)____ named Jean-Philippe stopped to chat and offered to show them around. He told them that Montreal had its own (9)____ culture, where two languages lived side by side. The cousins agreed that one day here was far too (10)____.', 146, 2, '[{"q":"1","answer":"C","options":["angry","asleep","happy","sorry"],"explanation":"tired but happy 累但开心。"},{"q":"2","answer":"D","options":["peaks","goats","drills","advertisements"],"explanation":"advertisements on the walls 墙上的广告。"},{"q":"3","answer":"A","options":["accent","mall","frost","shore"],"explanation":"with an accent 带着口音。"},{"q":"4","answer":"B","options":["Owing","Contrary","Heading","Speaking"],"explanation":"Contrary to what we expected 与预期相反。"},{"q":"5","answer":"C","options":["freeze","sell","proceed","drill"],"explanation":"proceed to the old part 前往老城区。"},{"q":"6","answer":"D","options":["frozen","urban","misty","antique"],"explanation":"antique furniture 古董家具。"},{"q":"7","answer":"A","options":["dusk","steel","toast","peak"],"explanation":"by dusk 到黄昏时。"},{"q":"8","answer":"B","options":["harbour","photographer","mall","quarry"],"explanation":"a young photographer 一位年轻摄影师。"},{"q":"9","answer":"C","options":["frozen","broken","unique","wealthy"],"explanation":"its own unique culture 独特的文化。"},{"q":"10","answer":"D","options":["long","loud","cold","short"],"explanation":"far too short 太短了。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U4', 'Liu Qian''s Travel Diary', 'Day five. We are now (1)____ east towards the coast, and the train has not stopped rocking all night. I am writing this (2)____ beside the broad river, which shines silver under the moon. So much has happened that it is hard to keep my notes (3)____. We crossed the great (4)____, climbed through the Rockies, and spent a few (5)____ hours in busy Toronto. In Montreal we met a kind (6)____ who told us we (7)____ it to ourselves to come back. The (8)____ of the whole trip, for me, was the morning the lake appeared outside our window. Tonight I feel (9)____ but happy. Tomorrow we reach the sea, and our long (10)____ across this vast land will finally come to an end.', 125, 2, '[{"q":"1","answer":"A","options":["heading","selling","freezing","drilling"],"explanation":"heading east 向东行进。"},{"q":"2","answer":"B","options":["mall","diary","frost","steel"],"explanation":"writing this diary 写日记。"},{"q":"3","answer":"C","options":["frozen","broken","coherent","urban"],"explanation":"keep my notes coherent 让笔记有条理。"},{"q":"4","answer":"D","options":["mall","drill","accent","prairie"],"explanation":"the great prairie 大草原。"},{"q":"5","answer":"A","options":["pleasant","frozen","broken","wealthy"],"explanation":"a few pleasant hours 愉快的几小时。"},{"q":"6","answer":"B","options":["mall","photographer","drill","quarry"],"explanation":"a kind photographer 一位友善的摄影师。"},{"q":"7","answer":"C","options":["sold","froze","owed","drilled"],"explanation":"owed it to ourselves 我们应该(给自己)。"},{"q":"8","answer":"D","options":["accent","frost","steel","highlight"],"explanation":"the highlight of the trip 旅程的亮点。"},{"q":"9","answer":"A","options":["tired","angry","afraid","sorry"],"explanation":"tired but happy 累但开心。"},{"q":"10","answer":"B","options":["mall","journey","drill","shore"],"explanation":"our long journey 漫长的旅程。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U4', 'My Great-Grandfather''s Railway', 'My family has always loved trains, and now I know (1)____. More than a hundred years ago, my great-grandfather helped to build the railway across this country. The work was hard and (2)____. The builders had to (3)____ through solid rock and lay (4)____ track over endless plains. Many of the workers, like him, had travelled (5)____ from China to find a new life. They worked through (6)____ winters when frost covered everything. (7)____ from today, their courage is difficult to imagine. When the line was finally (8)____, it tied the distant cities together at last. Now, (9)____ in a warm carriage, I watch the same spectacular land roll by. I feel proud of the countless hands that (10)____ this path through such a vast and difficult country.', 128, 2, '[{"q":"1","answer":"C","options":["where","when","why","whose"],"explanation":"know why 知道原因。"},{"q":"2","answer":"D","options":["pleasant","wealthy","urban","dangerous"],"explanation":"hard and dangerous 艰苦而危险。"},{"q":"3","answer":"A","options":["drill","sell","freeze","owe"],"explanation":"drill through rock 钻穿岩石。"},{"q":"4","answer":"B","options":["mall","steel","frost","shore"],"explanation":"steel track 钢轨。"},{"q":"5","answer":"C","options":["near","down","far","off"],"explanation":"travelled far 远道而来。"},{"q":"6","answer":"D","options":["pleasant","wealthy","coherent","freezing"],"explanation":"freezing winters 严寒的冬天。"},{"q":"7","answer":"A","options":["Seen","Seeing","To see","Sees"],"explanation":"Seen from today 从今天看(被动,主语 courage 被看)。"},{"q":"8","answer":"B","options":["sold","finished","lost","frozen"],"explanation":"finally finished 终于建成。"},{"q":"9","answer":"C","options":["sat","to sit","sitting","sits"],"explanation":"sitting in a carriage 坐在车厢里(现在分词作状语,主动)。"},{"q":"10","answer":"D","options":["wasted","forgot","lost","cut"],"explanation":"cut this path 开辟出这条路。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U4 听力·对话 Booking a Train Ticket', '选择性必修二 U4 · dialogue', 3, 'Clerk: Good morning. Where would you like to travel to?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U4 听力·短文 One of the World''s Longest Railways', '选择性必修二 U4 · passage', 2, 'The railway across Canada is one of the longest in the world.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U4 听力·对话 Skating on a Frozen Lake', '选择性必修二 U4 · dialogue', 3, 'Liu Qian: That lake looks so blue. Is it always like that?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U4 听力·短文 A Small Town on the Prairie', '选择性必修二 U4 · passage', 2, 'Our train stopped for a short while at a small prairie town.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U4 听力·对话 Asking the Way in the City', '选择性必修二 U4 · dialogue', 3, 'Daiyu: Excuse me, how far is the old town from here?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U4 听力·短文 A Tip for the Long Journey', '选择性必修二 U4 · passage', 2, 'Here is a simple tip for anyone taking a long rail journey.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (11, 'Write a Travel Diary about a Rail Journey(写一篇横穿大地的火车旅行日记)', 'A Day on the Train Across Canada', '假设你叫李华,正与同伴一起坐火车横穿一片辽阔的大地。请用英语写一篇约100词的旅行日记,内容包括:① 你今天到了哪里、看到了什么风景(用方位词描述);② 旅途中印象最深的一件事或遇到的一个人;③ 你此刻的感受。注意:用恰当的衔接词(first, then, later, eventually 等)让行文连贯,适当使用过去分词/现在分词作状语。', 'Suppose you are Li Hua. You are travelling by train across a vast land with a friend. Write a travel diary of about 100 words including: 1) where you reached today and the scenery you saw (use words of position and direction); 2) the most memorable thing or person you met along the way; 3) how you feel right now. Use discourse markers (first, then, later, eventually) to make your writing coherent.', '["到达地点与风景(Today we reached … / Heading east, we passed …)","印象最深的事/人(The highlight of the day was … / On the train we met …)","此刻的感受(Tired but happy, I felt …)","用衔接词连贯 + 分词作状语(Seeing …, I … / Seen from …, the … looked …)"]'::jsonb, 70, 100, 'Day three of our great rail journey. This morning, heading east, the train thundered on across the wide prairie, where golden wheat fields stretched as far as the eye could see. Later we climbed into the Rockies, and snowy peaks rose on every side. Seen from the train, the mountains looked almost unreal. The highlight of the day was meeting Anna, a friendly local who taught us Canadian idioms and pointed out a blue lake that freezes over in winter. Eventually night came, and I pulled back the curtain to watch the stars. Tired but happy, I feel lucky to be crossing such a vast and beautiful land.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Heading east, the train thundered on across the wide prairie.","Seen from the train, the snowy mountains looked almost unreal.","The highlight of the day was meeting Anna, a friendly local passenger.","Tired but happy, I feel lucky to be crossing such a vast and beautiful land."]'::jsonb, '[{"wrong":"Seeing from the train, the lake looked blue.","correct":"Seen from the train, the lake looked blue.","note":"lake 是被''看''的承受者,作状语用过去分词 Seen(被动)。"},{"wrong":"The train thundered on cross the prairie.","correct":"The train thundered on across the prairie.","note":"''横穿''用介词 across,不用动词 cross。"},{"wrong":"Tired but happily, I went to sleep.","correct":"Tired but happy, I went to sleep.","note":"并列作主语补足成分,这里用形容词 happy 与 tired 对应。"}]'::jsonb, '【火车旅行日记结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (11, 'elective2', 'U4', '{"title":"过去分词 vs 现在分词(done vs doing)速查","intro":"核心一句话:现在分词(doing)= 主动 / 进行;过去分词(done)= 被动 / 完成。判断时只看分词与它的逻辑主语(被修饰名词 / 句子主语 / 宾语)是''发出动作''还是''承受动作''。","table":{"headers":["位置","doing(主动/进行)","done(被动/完成)"],"rows":[["作定语","the train heading west(火车主动行驶)","the road covered with snow(路被雪覆盖)"],["作状语","Seeing the view, she smiled(她主动看)","Seen from the hill, the lake looks blue(湖被看)"],["作宾补","I saw him crossing the street(他主动过街)","I had my ticket checked(票被检查)"]]},"specialRules":[{"rule":"不及物动词没有被动,''已完成''用过去分词作定语","mark":"fallen leaves 落叶 / the risen sun 升起的太阳"},{"rule":"fall/rise/flow 等是主动进行时用 -ing","mark":"falling leaves 正在落的叶 / rising mist 升起的雾"},{"rule":"have / get + sth + done = ''让某事被做''(被动完成)","mark":"have my photos printed 把照片冲印好"},{"rule":"see/hear/find/watch + sb + doing(在做)/ done(被做完)","mark":"saw him crossing / found the window broken"}],"why":["分词没有自己的主语,它的逻辑主语就是被修饰的名词或句子主语;主语''发出''动作就主动(doing),主语''承受''动作就被动(done)——所以一切判断都归到主动还是被动这一条。"],"gaokaoPoints":["语法填空高频:给出动词原形,要你按主动/被动填 -ing 或 -ed(如 ___ from the hill, the lake … → Seen)。","区分 fallen/falling、covered/covering:看动作是''已完成/被动''还是''正在进行/主动''。","have sth done 与 see sb doing/done 的宾补辨析。"],"examVsReal":[{"exam":"Seen from the plane, the city looked small.(考试/书面)","real":"When you see it from the plane, the city looks small.","note":"考试爱考分词作状语;口语里常直接用从句说清楚。"},{"exam":"I had my ticket checked.(考试 have sth done)","real":"Someone checked my ticket. / They checked my ticket.","note":"考试用 have sth done 强调''被做'';口语常直接用主动句。"}]}'::jsonb);
